// @ts-check
// Regenerated by ../tools/regenerate-canonical-vectors.mjs without importing this module.

import test, { describe } from "node:test";
import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import {
  PERIOD_CHAIN_CONSTRUCTION,
  PERIOD_CHAIN_STATE_BYTES,
  periodChainConstructionProfile,
  periodChainCoordinatePrimitive,
  periodChainDerivations,
  periodChainLabelPrimitive,
  periodChainLabelAt,
  periodChainLeafPrimitive,
  periodChainRootPrimitive,
  periodChainStepPrimitive,
  settlePeriodChainGeometry,
} from "../core-shared/periodChainConstruction.js";
import { base64urlEncode } from "../../../core-shared/codec.js";

const VECTORS = JSON.parse(
  readFileSync(new URL("./fixtures/dca-period-chain-v1.vectors.json", import.meta.url), "utf8"),
);
assert.equal(VECTORS.setIdentity, PERIOD_CHAIN_CONSTRUCTION);
assert.equal(VECTORS.status, "canonical-16");
assert.deepEqual(VECTORS.semanticWidths, {
  chainState: 16,
  contentKey: 16,
  exactLeaf: 16,
  exactWrapAlgorithm: "AES-128-GCM",
  keyDerivationSecret: 32,
});

/** @param {string} hex */
function bytes(hex) {
  return Uint8Array.from(hex.match(/../g) ?? [], (pair) => Number.parseInt(pair, 16));
}
/** @param {any} vector */
function geometryOf(vector) {
  return settlePeriodChainGeometry({
    chainsPerDay: vector.chainsPerDay,
    periodMinutes: vector.periodMinutes,
  });
}
/** @param {any} vector */
function terminalLabelOf(vector) {
  return periodChainLabelAt(vector.windowStart + (vector.N - 1) * vector.periodMinutes);
}
const canonical = periodChainDerivations(PERIOD_CHAIN_CONSTRUCTION);

describe("The canonical dca-period-chain-v1 construction", () => {
  test("exports the five one-call primitives the neutral bridge observes", async () => {
    const vector = VECTORS.cases[0];
    const geometry = { chainsPerDay: vector.chainsPerDay, periodMinutes: vector.periodMinutes };
    const terminal = await periodChainRootPrimitive({
      keyDerivationSecret: bytes(vector.secretHex),
      accessGroup: vector.accessGroup,
      ...geometry,
      windowStart: vector.windowStart,
    });
    assert.deepEqual(periodChainCoordinatePrimitive({ t: vector.label, ...geometry }), {
      windowStart: vector.windowStart,
      position: vector.position,
    });
    assert.equal(
      periodChainLabelPrimitive({
        ...geometry,
        windowStart: vector.windowStart,
        position: vector.position,
      }),
      vector.label,
    );
    assert.equal(base64urlEncode(terminal), vector.terminal, "Root is one terminal derivation");
    const stepped = await periodChainStepPrimitive({
      state: terminal,
      accessGroup: vector.accessGroup,
      ...geometry,
      windowStart: vector.windowStart,
      position: vector.N - 2,
    });
    assert.equal(
      base64urlEncode(stepped),
      vector.stateAfterOneStep,
      "Step binds exactly terminal - 1",
    );
    const stateAtLabel = await canonical.stateFromState({
      state: terminal,
      accessGroup: vector.accessGroup,
      suppliedT: terminalLabelOf(vector),
      targetT: vector.label,
      geometry: geometryOf(vector),
    });
    const leaf = await periodChainLeafPrimitive({
      state: stateAtLabel,
      accessGroup: vector.accessGroup,
      ...geometry,
      windowStart: vector.windowStart,
      position: vector.position,
    });
    assert.equal(
      base64urlEncode(leaf),
      vector.leaf,
      "Leaf binds one supplied state at its position",
    );
    await assert.rejects(
      periodChainStepPrimitive({
        state: terminal,
        accessGroup: vector.accessGroup,
        ...geometry,
        windowStart: vector.windowStart,
        position: vector.N - 1,
      }),
      /one period-chain Step/,
    );
  });

  test("direct Label, Root, Step and Leaf reject a windowStart that is not on their geometry grid", async () => {
    const vector = VECTORS.cases[0];
    const geometry = { chainsPerDay: vector.chainsPerDay, periodMinutes: vector.periodMinutes };
    const misalignedWindowStart = vector.windowStart + 1;
    const terminal = await periodChainRootPrimitive({
      keyDerivationSecret: bytes(vector.secretHex),
      accessGroup: vector.accessGroup,
      ...geometry,
      windowStart: vector.windowStart,
    });
    assert.throws(
      () =>
        periodChainLabelPrimitive({
          ...geometry,
          windowStart: misalignedWindowStart,
          position: vector.position,
        }),
      /off the 15-minute family grid/,
    );
    await assert.rejects(
      periodChainRootPrimitive({
        keyDerivationSecret: bytes(vector.secretHex),
        accessGroup: vector.accessGroup,
        ...geometry,
        windowStart: misalignedWindowStart,
      }),
      /off the 15-minute family grid/,
    );
    await assert.rejects(
      periodChainStepPrimitive({
        state: terminal,
        accessGroup: vector.accessGroup,
        ...geometry,
        windowStart: misalignedWindowStart,
        position: vector.N - 2,
      }),
      /off the 15-minute family grid/,
    );
    await assert.rejects(
      periodChainLeafPrimitive({
        state: terminal,
        accessGroup: vector.accessGroup,
        ...geometry,
        windowStart: misalignedWindowStart,
        position: vector.position,
      }),
      /off the 15-minute family grid/,
    );
  });

  test("has the one fixed 16-byte state profile", () => {
    const profile = periodChainConstructionProfile(PERIOD_CHAIN_CONSTRUCTION);
    assert.equal(profile.constructionId, PERIOD_CHAIN_CONSTRUCTION);
    assert.equal(profile.stateBytes, PERIOD_CHAIN_STATE_BYTES);
    assert.equal(profile.stateBytes, 16);
  });

  test("derives every regenerated Root, Step, Leaf and expansion", async () => {
    for (const vector of VECTORS.cases) {
      const geometry = geometryOf(vector);
      const terminalT = terminalLabelOf(vector);
      const terminal = await canonical.terminalState({
        keyDerivationSecret: bytes(vector.secretHex),
        accessGroup: vector.accessGroup,
        terminalT,
        geometry,
      });
      assert.equal(terminal.length, 16, `${vector.id}: Root width`);
      assert.equal(base64urlEncode(terminal), vector.terminal, `${vector.id}: Root`);
      const expansion = await canonical.expansionFromState({
        state: terminal,
        accessGroup: vector.accessGroup,
        suppliedT: terminalT,
        cutoffT: terminalT,
        geometry,
      });
      assert.equal(expansion.length, vector.N, `${vector.id}: expansion length`);
      assert.deepEqual(
        expansion.map((entry) => base64urlEncode(entry.key)),
        vector.expansion,
        `${vector.id}: expansion`,
      );
      const step = await canonical.stateFromState({
        state: terminal,
        accessGroup: vector.accessGroup,
        suppliedT: terminalT,
        targetT: expansion.at(-2).t,
        geometry,
      });
      assert.equal(base64urlEncode(step), vector.stateAfterOneStep, `${vector.id}: Step`);
      const state = await canonical.stateFromState({
        state: terminal,
        accessGroup: vector.accessGroup,
        suppliedT: terminalT,
        targetT: vector.label,
        geometry,
      });
      const leaf = await canonical.leafFromState({
        state,
        accessGroup: vector.accessGroup,
        t: vector.label,
        geometry,
      });
      assert.equal(base64urlEncode(leaf), vector.leaf, `${vector.id}: Leaf`);
    }
  });

  test("records the intentional Root-prefix and recomputed Step/Leaf migration", () => {
    assert.match(VECTORS.replacement, /Root is the first 16 bytes/);
    assert.match(VECTORS.replacement, /Step and Leaf are recomputed/);
    assert.equal(VECTORS.semanticWidths.keyDerivationSecret, 32);
  });

  test("refuses 15, 17, 24 and 32-byte supplied chain states", async () => {
    const vector = VECTORS.cases[0];
    const geometry = geometryOf(vector);
    for (const width of [15, 17, 24, 32]) {
      await assert.rejects(
        canonical.leafFromState({
          state: new Uint8Array(width),
          accessGroup: vector.accessGroup,
          t: vector.label,
          geometry,
        }),
        (error) => error.code === "bad_config" && /exactly 16 bytes/.test(error.message),
      );
    }
  });

  test("keeps the key-derivation secret at exactly 32 bytes", async () => {
    const vector = VECTORS.cases[0];
    for (const width of [15, 16, 17, 24, 31, 33]) {
      await assert.rejects(
        canonical.terminalState({
          keyDerivationSecret: new Uint8Array(width),
          accessGroup: vector.accessGroup,
          terminalT: terminalLabelOf(vector),
          geometry: geometryOf(vector),
        }),
        (error) =>
          error.code === "bad_config" &&
          /exactly 32 key-derivation-secret bytes/.test(error.message),
      );
    }
  });

  test("refuses the retired secret member even beside the selected input", async () => {
    const vector = VECTORS.cases[0];
    await assert.rejects(
      canonical.terminalState({
        keyDerivationSecret: bytes(vector.secretHex),
        secret: undefined,
        accessGroup: vector.accessGroup,
        terminalT: terminalLabelOf(vector),
        geometry: geometryOf(vector),
      }),
      (error) =>
        error.code === "unsupported_option" &&
        /keyDerivationSecret, not secret/.test(error.message),
    );
  });

  test("refuses unsupported construction names rather than treating width as a selector", () => {
    for (const name of ["dca-period-chain-24-v1", "dca-period-chain", "", 16]) {
      assert.throws(
        () => periodChainConstructionProfile(/** @type {any} */ (name)),
        /construction profile/,
      );
      assert.throws(
        () => periodChainDerivations(/** @type {any} */ (name)),
        /construction profile/,
      );
    }
  });
});
